import {SCENARIOS,PLAYERS,position} from './engine.js';import {auditEvidence} from './evidence-audit.js';import {fetchReview} from './review-client.js';
const $=id=>document.getElementById(id),s=SCENARIOS[0],original={scenario:'wide',time:16,corrected:false,tracking:true,language:'en'};
const chapters=[{at:0,title:'Watch the unseen run.',copy:'Moreau runs wide. Laurent moves toward the same side in the original record. That timing is an observation, not proof that one caused the other.'},{at:20,title:'Ask a better question.',copy:'“Did the run cause the defender to move?” The first review separates observation, explanation, calculation and uncertainty.'},{at:40,title:'Change the evidence.',copy:'The corrected source holds Laurent at his starting position. The crew must withdraw that movement claim, preserve the passes, and consider what evidence would distinguish alternative explanations.'},{at:65,title:'Same facts. Different understanding.',copy:'A beginner needs the football concept. An analyst needs the positional consequence, calculation and limitations. Compare both below.'}];
let seconds=0,running=false,last=0,timer=null,live=false,audience='beginner',generation=0,controller=null,records=[],requested=new Set(),paintKey='';
const node=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n;};
chapters.forEach((c,i)=>{const b=node('button',`0${i+1} · ${['Watch','Question','Correct','Personalize'][i]}`);b.onclick=()=>{if(live&&running){$('demo-status').textContent='Pause or reset the live demonstration before jumping chapters.';return;}seconds=c.at;render();};$('chapters').append(b);});
function render(){$('clock').textContent=`${Math.floor(seconds)} / 90 s`;$('progress').value=seconds;const key=JSON.stringify([chapters.findLastIndex(c=>seconds>=c.at),live,audience,records]);if(key===paintKey)return;paintKey=key;const corrected=seconds>=40,a=auditEvidence({...original,corrected},corrected?original:null),index=chapters.findLastIndex(c=>seconds>=c.at);$('clock').textContent=`${Math.floor(seconds)} / 90 s`;$('progress').value=seconds;$('source').textContent=corrected?'CORRECTED TRACKING':'ORIGINAL TRACKING';$('chapter-label').textContent=`${index+1} / 4 · ${live?'LIVE REVIEW MODE':'REVIEWED EXPLANATIONS'}`;$('chapter-title').textContent=chapters[index].title;$('chapter-copy').textContent=chapters[index].copy;$('chapters').querySelectorAll('button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));$('audience-copy').textContent=a.audiences[audience];document.querySelectorAll('[data-audience]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.audience===audience)));
 $('ledger').replaceChildren(...a.ledger.map(r=>{const c=document.createElement('article');c.append(node('h3',{withdrawn:'Withdrawn / limited',preserved:'Preserved',uncertain:'Still uncertain'}[r.kind]),node('p',r.text));return c;}));
 const ns='http://www.w3.org/2000/svg',svg=$('pitch');svg.replaceChildren();const draw=(tag,attrs)=>{const n=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);svg.append(n);return n;};draw('rect',{x:3,y:3,width:99,height:62,fill:'none',stroke:'#afd5b8','stroke-width':.3});draw('path',{d:'M52.5 3V65M3 19H19V49H3M102 19H86V49H102',fill:'none',stroke:'#afd5b8','stroke-width':.3});draw('circle',{cx:52.5,cy:34,r:9,fill:'none',stroke:'#afd5b8','stroke-width':.3});
 const time=16;for(const p of PLAYERS){const xy=position(s,p.id,time,corrected);draw('circle',{cx:xy[0],cy:xy[1],r:[7,102].includes(p.id)?1.8:1.1,fill:p.id<100?'#e6ed83':'#8dd2f5',opacity:[7,102].includes(p.id)?1:.45});if([7,102].includes(p.id)){const start=position(s,p.id,0,corrected);draw('path',{d:`M${start.join(' ')} L${xy.join(' ')}`,stroke:'#fff','stroke-width':.5,'stroke-dasharray':'1 1'});const text=draw('text',{x:xy[0]+3,y:xy[1]+1,fill:'white','font-size':2.4});text.textContent=p.id===7?'MOREAU':'LAURENT';}}
 $('rounds').replaceChildren();for(const [i,r]of records.entries()){const d=document.createElement('details');d.open=i===records.length-1;d.append(node('summary',`Round ${r.round} · ${r.engine==='azure_selection'?(r.cached?'saved Azure result':'fresh Azure result'):'reviewed fallback'} · ${r.elapsed_ms||0} ms`));if(r.error)d.append(node('p','Validation / availability: '+r.error));for(const p of r.posts||[]){const c=document.createElement('article');c.append(node('h3',p.name),node('p',p.summary),node('small',p.evidence_ids.join(' · ')));if(p.working)c.append(node('code',p.working));d.append(c);}$('rounds').append(d);}if(!live){const c=document.createElement('article');c.append(node('h3','VECTOR / VERIFIED CALCULATION'),node('p',a.progression.summary),node('code',a.progression.equation));$('rounds').append(c);}
}
async function requestRound(round){if(requested.has(round))return;requested.add(round);const g=generation;try{const config=await fetch('api-config.json').then(r=>r.json()),base=['localhost','127.0.0.1'].includes(location.hostname)?'':config.baseUrl;const r=await fetchReview(base,{...original,corrected:round===2,intent:round===2?'challenge':'opening',previous:round===2?original:null},{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(45000)])});if(g!==generation)return;records.push({...r,round});records.sort((a,b)=>a.round-b.round);$('download').disabled=false;$('demo-status').textContent=`Round ${round}: ${r.engine==='azure_selection'?'Azure review verified':'AI unavailable; reviewed fallback clearly labeled'}.`;render();}catch(e){if(g!==generation)return;$('demo-status').textContent=`Round ${round}: ${e.message} Reset to retry. No automatic retry.`;}}
function tick(){const now=performance.now();if(running&&!document.hidden){seconds=Math.min(90,seconds+(now-last)/1000);if(live&&seconds>=40)requestRound(2);render();if(seconds===90){running=false;clearInterval(timer);$('pause').disabled=true;$('start').disabled=false;$('live').disabled=false;}}last=now;}
function reset(){generation++;controller?.abort();clearInterval(timer);running=false;seconds=0;records=[];requested.clear();$('pause').disabled=true;$('pause').textContent='Pause';$('start').disabled=false;$('live').disabled=false;$('download').disabled=true;}
function start(isLive){reset();live=isLive;controller=new AbortController();running=true;last=performance.now();$('start').disabled=true;$('live').disabled=true;$('pause').disabled=false;$('demo-status').textContent=isLive?'Live reviews requested at the opening and correction. Only verified results will appear.':'Reviewed mode: no model calls. Pause and explore any step.';if(live)requestRound(1);timer=setInterval(tick,250);render();}
$('start').onclick=()=>start(false);$('live').onclick=()=>start(true);$('reset').onclick=()=>{reset();live=false;$('demo-status').textContent='Ready. No automatic requests.';render();};$('pause').onclick=()=>{running=!running;last=performance.now();$('pause').textContent=running?'Pause':'Resume';};document.querySelectorAll('[data-audience]').forEach(b=>b.onclick=()=>{audience=b.dataset.audience;render();});window.addEventListener('pagehide',reset);
$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({captured_at:new Date().toISOString(),kind:'live-evidence-demo',records},null,2)],{type:'application/json'}));const a=node('a','');a.href=url;a.download='btr-live-evidence-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};render();
